csui.define('csui/utils/commands/table.settings.table.mode',[
  'require',
  'csui/models/command',
  "csui/utils/accessibility",
], function (require, CommandModel, Accessibility) {
  'use strict';

  const accessibleTable = Accessibility.isAccessibleTable();

  const TableSettingsTableModeCommand = CommandModel.extend({
    defaults: {
      signature: "TableSettingsTableMode"
    },

    enabled: function (status) {
      // for compatibility reasons, use the old module path to get the module config
      const thumbnailToggleConfig = require.moduleConfig('csui/utils/commands/thumbnail.toggle');
      const itemValue = status.toolItem.get('itemValue');
      switch (itemValue) {
      case 'wrap':
        if (accessibleTable) {
          return false; // list-mode is not for accessible table
        }
        break;
      case 'thumbnail':
        if (accessibleTable) {
          return false; // // thumbnail-mode is not for accessible table
        }
        if (thumbnailToggleConfig.enableGridView === false) {
          return false; // disable thumbnail command if grid (=thumbnail) mode is disabled
        }
        break;
      }

      return true;
    },

    execute: async function (status, options) {
      const nodesTableView = options.nodesTableView;
      const tableMode = options.itemValue;
      await nodesTableView.setTableMode(tableMode);
      // update the current table mode in the status object
      status.currentTableMode = tableMode;
    }

  });

  return TableSettingsTableModeCommand;
});
