csui.define('csui/utils/commands/switch.to.jato',[
  'csui/utils/commands/switch.to.smartview',
  "smart/themes/theming",
], function (SwitchToSmartviewCommand, theming) {
  "use strict";
  const SwitchToJato = SwitchToSmartviewCommand.extend({
    defaults: {
      signature: "SwitchToJato"
    },

    enabled: function (status, options) {
      return this.canSwitchToJatoTheme() && !theming.isJATOTheme();
    },

  });

  return SwitchToJato;
});
